import React from 'react';
import styles from './BookCard.module.css';

function BookCard({ book, user, onRequest }) {
  return (
    <div className={styles.card}>
      <div className={styles.title}>{book.title}</div>
      <div className={styles.author}>by {book.author}</div>
      {user?.role === 'student' && book.available && (
        <button className={styles.button} onClick={() => onRequest(book._id)}>Request</button>
      )}
      {!book.available && <span style={{ color: '#e53e3e', fontWeight: 600 }}>Not Available</span>}
    </div>
  );
}

export default BookCard;
